const out = [];

for (const item of $input.all()) {
  const t = item.json || {};

  let status = t.Status ?? t.status ?? '';
  if (status && typeof status === 'object' && !Array.isArray(status)) {
    status = status.name ?? '';
  }
  status = String(status || '').trim();

  if (!['Active', 'Paused', 'Done'].includes(status)) {
    continue;
  }

  const links = Array.isArray(t.agent_dialogs_v3)
    ? t.agent_dialogs_v3
    : [];

  for (const link of links) {
    const dialogId =
      typeof link === 'object'
        ? String(link.id || '').trim()
        : String(link || '').trim();

    if (!dialogId) continue;

    out.push({
      json: {
        airtable_task_id: String(t.id || '').trim(),
        task_name: String(t.Name_task || '').trim(),
        task_status: status,
        airtable_dialog_id: dialogId
      }
    });
  }
}

return out;

